solution.code:
enum Status {
  Active = 'ACTIVE',
  Done = 'DONE'
}

const value = 'ACTIVE';
const name = Object.keys(Status).find(k => Status[k as keyof typeof Status] === value);
console.log(name); // 'Active'

enum Direction {
  Up,
  Down,
  Left,
  Right
}

function enumNames(e: Record<string, string | number>): string[] {
  return Object.keys(e).filter(k => isNaN(Number(k)));
}

console.log(enumNames(Direction)); // ['Up','Down','Left','Right']
